## Why This Is Asked
This question tests the candidate's ability to design a complete, event-driven serverless architecture on AWS while addressing real-world concerns like data validation, privacy, and cost optimization. It demonstrates practical knowledge of core AWS services and their integration patterns.

## Key Concepts
- Event-driven architecture (S3 event notifications, Lambda triggers)
- JSON Schema validation for data quality and contract enforcement
- AWS Comprehend for NLP (sentiment analysis and topic detection)
- Data enrichment and indexing with DynamoDB
- Privacy controls: PII masking, KMS encryption, least-privilege IAM roles
- Cost considerations: payload size limits, Lambda concurrency, Comprehend pricing

## Code Example
```javascript
// Node.js Lambda skeleton
const AWS = require('aws-sdk');
const Ajv = require('ajv');

const s3 = new AWS.S3();
const comprehend = new AWS.Comprehend();
const docClient = new AWS.DynamoDB.DocumentClient();
const ajv = new Ajv();

const schema = {
  type: 'object',
  required: ['feedbackId', 'userId', 'feedbackText'],
  properties: {
    feedbackId: { type: 'string' },
    userId: { type: 'string' },
    feedbackText: { type: 'string', maxLength: 3000 }
  }
};

exports.handler = async (event) => {
  const bucket = event.Records[0].s3.bucket.name;
  const key = decodeURIComponent(event.Records[0].s3.object.key);

  try {
    const { Body } = await s3.getObject({ Bucket: bucket, Key: key }).promise();
    const data = JSON.parse(Body);

    const valid = ajv.validate(schema, data);
    if (!valid) throw new Error(`Validation failed: ${ajv.errorsText()}`);

    const anonymizedUserId = hashUserId(data.userId);

    const comprehendResult = await comprehend.detectSentiment({
      Text: data.feedbackText,
      LanguageCode: 'en'
    }).promise();

    const topicsResult = await comprehend.listTopicsDetectionJobs().promise();

    const enriched = {
      feedbackId: data.feedbackId,
      anonymizedUserId,
      sentiment: comprehendResult.Sentiment,
      sentimentScore: comprehendResult.SentimentScore,
      originalKey: key,
      processedAt: new Date().toISOString()
    };

    await s3.putObject({
      Bucket: process.env.OUTPUT_BUCKET,
      Key: `enriched/${data.feedbackId}.json`,
      Body: JSON.stringify(enriched),
      ContentType: 'application/json'
    }).promise();

    await docClient.put({
      TableName: process.env.DYNAMO_TABLE,
      Item: enriched
    }).promise();

    return { statusCode: 200 };
  } catch (error) {
    console.error('Error:', error);
    throw error;
  }
};

function hashUserId(userId) {
  return require('crypto').createHash('sha256').update(userId).digest('hex').substring(0, 16);
}
```

